-- ========================================================
-- Supabase Schema & Data Migration for Yooloei House
-- วิธีใช้: นำโค้ดทั้งหมดนี้ไปวางใน Supabase > SQL Editor แล้วกด "Run"
-- ========================================================

-- 1. ตารางผู้ใช้งาน (USERS)
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  full_name TEXT,
  first_name TEXT,
  last_name TEXT,
  phone TEXT,
  username TEXT,
  avatar_url TEXT,
  role TEXT DEFAULT 'user' CHECK (role IN ('user', 'owner', 'admin')),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. ตารางหอพัก (DORMITORIES)
CREATE TABLE IF NOT EXISTS dormitories (
  id TEXT PRIMARY KEY,
  owner_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  owner_name TEXT,
  name TEXT NOT NULL,
  district TEXT NOT NULL,
  address TEXT NOT NULL,
  description TEXT,
  phone TEXT,
  line_id TEXT,
  price_min NUMERIC DEFAULT 0,
  price_max NUMERIC DEFAULT 0,
  amenities TEXT DEFAULT '[]',
  room_types TEXT DEFAULT '[]',
  images TEXT DEFAULT '[]',
  rating NUMERIC DEFAULT 0,
  review_count INTEGER DEFAULT 0,
  view_count INTEGER DEFAULT 0,
  favorite_count INTEGER DEFAULT 0,
  status TEXT DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
  latitude DOUBLE PRECISION,
  longitude DOUBLE PRECISION,
  location_status TEXT DEFAULT 'pending',
  location_updated_at TEXT,
  location_verified_at TEXT,
  location_verified_by TEXT,
  location_reject_reason TEXT,
  is_recommended INTEGER DEFAULT 0,
  recommended_order INTEGER DEFAULT 999,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. ตารางห้องพัก (ROOMS)
CREATE TABLE IF NOT EXISTS rooms (
  id TEXT PRIMARY KEY,
  dormitory_id TEXT REFERENCES dormitories(id) ON DELETE CASCADE,
  owner_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  room_number TEXT NOT NULL,
  room_type TEXT NOT NULL,
  price NUMERIC DEFAULT 0,
  status TEXT DEFAULT 'available' CHECK (status IN ('available', 'reserved', 'occupied')),
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. ตารางการจอง (BOOKINGS)
CREATE TABLE IF NOT EXISTS bookings (
  id TEXT PRIMARY KEY,
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  user_email TEXT,
  user_name TEXT,
  user_phone TEXT,
  owner_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  dormitory_id TEXT REFERENCES dormitories(id) ON DELETE CASCADE,
  dormitory_name TEXT NOT NULL,
  room_id TEXT,
  room_number TEXT,
  booking_date TEXT NOT NULL,
  note TEXT,
  status TEXT DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'cancelled', 'completed')),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. ตารางรีวิว (REVIEWS)
CREATE TABLE IF NOT EXISTS reviews (
  id TEXT PRIMARY KEY,
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  user_name TEXT,
  user_photo TEXT,
  dormitory_id TEXT REFERENCES dormitories(id) ON DELETE CASCADE,
  rating INTEGER DEFAULT 5 CHECK (rating >= 1 AND rating <= 5),
  comment TEXT NOT NULL,
  owner_reply TEXT,
  owner_reply_name TEXT,
  owner_reply_photo TEXT,
  owner_reply_role TEXT,
  owner_reply_at TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. ตารางรายการโปรด (FAVORITES)
CREATE TABLE IF NOT EXISTS favorites (
  id TEXT PRIMARY KEY,
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  dormitory_id TEXT REFERENCES dormitories(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(user_id, dormitory_id)
);

-- 7. ตารางข้อความแชท (MESSAGES)
CREATE TABLE IF NOT EXISTS messages (
  id TEXT PRIMARY KEY,
  sender_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  sender_name TEXT,
  receiver_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  receiver_name TEXT,
  dormitory_id TEXT,
  dormitory_name TEXT,
  message TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  is_read INTEGER DEFAULT 0
);

-- 8. ตารางประวัติการดูหอพัก (VIEW_HISTORY)
CREATE TABLE IF NOT EXISTS view_history (
  id TEXT PRIMARY KEY,
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  dormitory_id TEXT REFERENCES dormitories(id) ON DELETE CASCADE,
  viewed_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(user_id, dormitory_id)
);

-- 9. ตารางการแจ้งเตือน (NOTIFICATIONS)
CREATE TABLE IF NOT EXISTS notifications (
  id TEXT PRIMARY KEY,
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  message TEXT NOT NULL,
  type TEXT DEFAULT 'system',
  link TEXT,
  is_read INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 10. ตารางบันทึกกิจกรรม (SYSTEM_LOGS)
CREATE TABLE IF NOT EXISTS system_logs (
  id TEXT PRIMARY KEY,
  action TEXT NOT NULL,
  details TEXT,
  performed_by TEXT NOT NULL,
  type TEXT DEFAULT 'system',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 11. ตารางพื้นที่ / โซน (LOCATIONS)
CREATE TABLE IF NOT EXISTS locations (
  id TEXT PRIMARY KEY,
  name TEXT UNIQUE NOT NULL,
  description TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 12. ตารางตั้งค่าระบบ (SYSTEM_SETTINGS)
CREATE TABLE IF NOT EXISTS system_settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 13. ตารางประเภทห้อง / การเช่า (ROOM_TYPES)
CREATE TABLE IF NOT EXISTS room_types (
  id TEXT PRIMARY KEY,
  name TEXT UNIQUE NOT NULL,
  category TEXT DEFAULT 'ทั่วไป',
  description TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 14. ตารางประกาศข่าวสารหน้าแรก (ANNOUNCEMENTS)
CREATE TABLE IF NOT EXISTS announcements (
  id TEXT PRIMARY KEY,
  title TEXT,
  content TEXT,
  image_url TEXT,
  link_url TEXT,
  badge_text TEXT,
  status TEXT DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  layout_type TEXT DEFAULT 'auto',
  start_date TEXT,
  end_date TEXT,
  created_by TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- ปิด Row Level Security (RLS) เพื่อให้ระบบเชื่อมต่อได้อย่างสมบูรณ์
ALTER TABLE users DISABLE ROW LEVEL SECURITY;
ALTER TABLE dormitories DISABLE ROW LEVEL SECURITY;
ALTER TABLE rooms DISABLE ROW LEVEL SECURITY;
ALTER TABLE bookings DISABLE ROW LEVEL SECURITY;
ALTER TABLE reviews DISABLE ROW LEVEL SECURITY;
ALTER TABLE favorites DISABLE ROW LEVEL SECURITY;
ALTER TABLE messages DISABLE ROW LEVEL SECURITY;
ALTER TABLE view_history DISABLE ROW LEVEL SECURITY;
ALTER TABLE notifications DISABLE ROW LEVEL SECURITY;
ALTER TABLE system_logs DISABLE ROW LEVEL SECURITY;
ALTER TABLE locations DISABLE ROW LEVEL SECURITY;
ALTER TABLE system_settings DISABLE ROW LEVEL SECURITY;
ALTER TABLE room_types DISABLE ROW LEVEL SECURITY;
ALTER TABLE announcements DISABLE ROW LEVEL SECURITY;

